const LOGO_BASE = 'https://raw.githubusercontent.com/filippofilip95/car-logos-dataset/master/logos/optimized/'
const LOGO_SLUG: Record<string, string> = {
  'VW': 'volkswagen', 'Volkswagen': 'volkswagen',
  'Audi': 'audi', 'BMW': 'bmw',
  'Mercedes-Benz': 'mercedes-benz', 'Mercedes': 'mercedes-benz',
  'Opel': 'opel', 'Ford': 'ford',
  'Renault': 'renault', 'SEAT': 'seat', 'Seat': 'seat',
  'Škoda': 'skoda', 'Skoda': 'skoda',
  'Toyota': 'toyota', 'Honda': 'honda', 'Nissan': 'nissan',
  'Hyundai': 'hyundai', 'Kia': 'kia', 'KIA': 'kia',
  'Volvo': 'volvo', 'Fiat': 'fiat',
  'Citroën': 'citroen', 'Citroen': 'citroen',
  'Mazda': 'mazda', 'Mitsubishi': 'mitsubishi',
  'Suzuki': 'suzuki', 'Alfa Romeo': 'alfa-romeo',
  'Porsche': 'porsche', 'Ferrari': 'ferrari',
  'Lamborghini': 'lamborghini', 'Dacia': 'dacia',
  'Jeep': 'jeep', 'Maserati': 'maserati',
  'Jaguar': 'jaguar', 'Mini': 'mini', 'MINI': 'mini',
  'Tesla': 'tesla', 'Lexus': 'lexus',
  'Land Rover': 'land-rover', 'Range Rover': 'land-rover',
  'Cupra': 'cupra', 'Genesis': 'genesis', 'Peugeot': 'peugeot',
  'Subaru': 'subaru', 'Chevrolet': 'chevrolet',
  'Bentley': 'bentley', 'Smart': 'smart', 'BYD': 'byd',
  'Abarth': 'abarth', 'Rolls-Royce': 'rolls-royce',
  'Dodge': 'dodge', 'Lancia': 'lancia', 'Infiniti': 'infiniti', 'MG': 'mg',
  'Alpine': 'alpine', 'Polestar': 'polestar', 'Saab': 'saab',
  'DS': 'ds', 'DS Automobiles': 'ds',
  'Chrysler': 'chrysler', 'Cadillac': 'cadillac',
}

function BrandLogo({
  brand,
  className = 'car-brand-logo',
  size = 'md',
  mono = false,
}: {
  brand: string
  className?: string
  size?: 'sm' | 'md' | 'lg'
  mono?: boolean
}) {
  const style = BRAND_STYLE[brand] ?? { bg: '#e30613', fg: '#fff' }
  const abbr = BRAND_ABBR[brand] ?? brand.slice(0, brand.includes(' ') ? brand.indexOf(' ') : 4).toUpperCase()
  const [failed, setFailed] = useState(false)
  const slug = LOGO_SLUG[brand]
  const d = size === 'sm' ? 18 : size === 'lg' ? 30 : 24
  const hasLogo = slug && !failed
  return (
    <span className={className} style={hasLogo ? undefined : (mono ? undefined : { background: style.bg, color: style.fg })}>
      {hasLogo
        // eslint-disable-next-line @next/next/no-img-element
        ? <img
            src={`${LOGO_BASE}${slug}.png`}
            alt={brand} width={d} height={d}
            style={{ display: 'block', objectFit: 'contain' }}
            onError={() => setFailed(true)}
          />
        : abbr
      }
    </span>
  )
}

function SpecRow({ label, value, icon }: { label: string; value: string; icon?: React.ReactNode }) {
  return (
    <div className="cdm-spec-row">
      <span className="cdm-spec-label">
        {icon && <span className="cdm-spec-icon">{icon}</span>}
        {label}
      </span>
      <span className="cdm-spec-value">{value}</span>
    </div>
  )
}

