interface Props {
  car: WillhabenCar
  allCars?: WillhabenCar[]
  onClose: () => void
  onBook: () => void
  onCarSelect?: (car: WillhabenCar) => void
  isFav?: boolean
  onFav?: () => void
  recentlyViewed?: WillhabenCar[]
}

export default function CarDetailModal({ car, allCars, onClose, onBook, onCarSelect, isFav, onFav, recentlyViewed }: Props) {
  const [activeImg, setActiveImg]       = useState(0)
  const [showFullDesc, setShowFullDesc] = useState(false)
  const [showAllEquip, setShowAllEquip] = useState(false)
  const [isDragging, setIsDragging]     = useState(false)
  const [sliderDelta, setSliderDelta]   = useState(0)
  const [trackAnimate, setTrackAnimate] = useState(false)
  const [showKontakt, setShowKontakt]   = useState(false)

  // Finanzierungsrechner
  const [calcAnzahlung, setCalcAnzahlung] = useState(() => Math.max(0, Math.round(car.price * 0.1 / 100) * 100))
  const [calcLaufzeit,  setCalcLaufzeit]  = useState(48)
  const [calcZins,      setCalcZins]      = useState(6.9)

  // Zoom overlay state
  const [zoomOpen,  setZoomOpen]  = useState(false)
  const [zoomScale, setZoomScale] = useState(1)
  const [panX, setPanX]           = useState(0)
  const [panY, setPanY]           = useState(0)
  const [isPanning, setIsPanning] = useState(false)

  const [shareToast,  setShareToast]  = useState(false)
  const shareToastRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  function handleShare() {
    const url = `${window.location.origin}/?car=${car.id}#autocenter`
    if (typeof navigator !== 'undefined' && navigator.share) {
      navigator.share({ title: car.title, url }).catch(() => {})
    } else {
      navigator.clipboard?.writeText(url).then(() => {
        setShareToast(true)
        if (shareToastRef.current) clearTimeout(shareToastRef.current)
        shareToastRef.current = setTimeout(() => setShareToast(false), 2500)
      }).catch(() => {})
    }
  }

  function handleAsk() { setShowKontakt(true) }

  const sliderDragX    = useRef<number | null>(null)
  const thumbsRef      = useRef<HTMLDivElement>(null)
  const panStartRef    = useRef<{ x: number; y: number; px: number; py: number } | null>(null)
  const scrollBodyRef  = useRef<HTMLDivElement>(null)
  const cdmThumbRef    = useRef<HTMLDivElement>(null)
  const cdmIndicatorRef= useRef<HTMLDivElement>(null)
  const cdmRafRef      = useRef<number | null>(null)

  const [detail, setDetail] = useState<{
    description: string; equipment: string[]
    color: string; doors: number|null; seats: number|null
    owners: number|null; drive: string; condition: string; url: string
  } | null>(null)

  useEffect(() => {
    setDetail(null)
    fetch(`/api/vehicle-desc?id=${car.id}`)
      .then(r => r.json()).then(setDetail).catch(() => {})
  }, [car.id])

  const imgs  = car.images.length > 0 ? car.images : car.image ? [car.image] : []
  const brand = car.make || (car.title.split(' ')[0] ?? '')
  const desc  = detail?.description || car.description
  const equip = detail?.equipment?.length ? detail.equipment : car.equipment

  useEffect(() => {
    document.body.style.overflow = 'hidden'
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (zoomOpen) { closeZoom(); return }
        onClose()
      }
      if (!zoomOpen) {
        if (e.key === 'ArrowLeft'  && activeImg > 0)               goTo(activeImg - 1)
        if (e.key === 'ArrowRight' && activeImg < imgs.length - 1) goTo(activeImg + 1)
      }
    }
    document.addEventListener('keydown', onKey)
    return () => { document.body.style.overflow = ''; document.removeEventListener('keydown', onKey) }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onClose, activeImg, imgs.length, zoomOpen])

  useEffect(() => {
    const el = thumbsRef.current
    if (!el) return
    const thumb = el.children[activeImg] as HTMLElement | undefined
    thumb?.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' })
  }, [activeImg])

  function updateCdmSb(el: HTMLDivElement) {
    const thumb = cdmThumbRef.current
    if (!thumb) return
    const ratio  = el.clientHeight / el.scrollHeight
    const thumbH = Math.max(ratio * el.clientHeight, 30)
    const maxTop = el.clientHeight - thumbH
    const thumbT = el.scrollHeight > el.clientHeight
      ? (el.scrollTop / (el.scrollHeight - el.clientHeight)) * maxTop
      : 0
    thumb.style.height    = thumbH + 'px'
    thumb.style.transform = `translateY(${thumbT}px)`
  }
  function handleBodyScroll() {
    if (cdmRafRef.current) cancelAnimationFrame(cdmRafRef.current)
    cdmRafRef.current = requestAnimationFrame(() => {
      const el  = scrollBodyRef.current
      const ind = cdmIndicatorRef.current
      if (!el) return
      const hasMore = el.scrollTop + el.clientHeight < el.scrollHeight - 24
      if (ind) ind.style.display = hasMore ? 'flex' : 'none'
      updateCdmSb(el)
    })
  }

  useEffect(() => {
    const el  = scrollBodyRef.current
    const ind = cdmIndicatorRef.current
    if (!el) return
    if (ind) ind.style.display = el.scrollHeight > el.clientHeight + 24 ? 'flex' : 'none'
    updateCdmSb(el)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const calcMonthly = useMemo(() => {
    const summe = car.price - calcAnzahlung
    if (summe <= 0 || car.price <= 0) return 0
    const r = calcZins / 100 / 12
    const n = calcLaufzeit
    if (r === 0) return summe / n
    return (summe * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1)
  }, [car.price, calcAnzahlung, calcLaufzeit, calcZins])

  const similarCars = useMemo(() => {
    if (!allCars?.length) return []
    return allCars
      .filter(c => c.id !== car.id && (
        c.make === car.make ||
        (car.price > 0 && c.price > 0 && Math.abs(c.price - car.price) / car.price < 0.3)
      ))
      .sort((a, b) => (a.make === car.make ? 0 : 1) - (b.make === car.make ? 0 : 1))
      .slice(0, 4)
  }, [allCars, car])

  // ── Slider helpers ─────────────────────────────────────────
  function goTo(i: number) { setTrackAnimate(true); setActiveImg(i) }
  function goPrev() { if (activeImg > 0) goTo(activeImg - 1) }
  function goNext() { if (activeImg < imgs.length - 1) goTo(activeImg + 1) }

  function sliderStart(x: number) { sliderDragX.current = x; setTrackAnimate(false); setIsDragging(true) }
  function sliderMove(x: number)  { if (sliderDragX.current === null) return; setSliderDelta(x - sliderDragX.current) }
  function sliderEnd(x: number) {
    if (sliderDragX.current === null) return
    const delta = x - sliderDragX.current
    setTrackAnimate(true); setSliderDelta(0)
    if (delta < -50 && activeImg < imgs.length - 1) setActiveImg(i => i + 1)
    else if (delta > 50 && activeImg > 0) setActiveImg(i => i - 1)
    sliderDragX.current = null; setIsDragging(false)
  }

  // ── Zoom helpers ────────────────────────────────────────────
  function openZoom()  { setZoomOpen(true); setZoomScale(1); setPanX(0); setPanY(0) }
  function closeZoom() { setZoomOpen(false) }

  function onZoomPanStart(x: number, y: number) {
    if (zoomScale <= 1) return
    panStartRef.current = { x, y, px: panX, py: panY }
    setIsPanning(true)
  }
  function onZoomPanMove(x: number, y: number) {
    if (!panStartRef.current) return
    setPanX(panStartRef.current.px + x - panStartRef.current.x)
    setPanY(panStartRef.current.py + y - panStartRef.current.y)
  }
  function onZoomPanEnd() { panStartRef.current = null; setIsPanning(false) }

  function onZoomClick(e: React.MouseEvent) {
    e.stopPropagation()
    if (zoomScale >= 2) { setZoomScale(1); setPanX(0); setPanY(0) }
    else setZoomScale(2.5)
  }


  return (
    <>
      <div className="cdm-backdrop" onClick={onClose}>
        <div className="cdm-modal" onClick={e => e.stopPropagation()} role="dialog" aria-modal="true">

          <button className="cdm-close" onClick={onClose} aria-label="Schließen">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
              <path d="M18 6 6 18M6 6l12 12"/>
            </svg>
          </button>

          {/* ── Gallery ───────────────────────────── */}
          <div className="cdm-gallery">

            {/* Main slider */}
            <div
              className="cdm-slider-outer"
              style={{ cursor: imgs.length > 1 ? (isDragging ? 'grabbing' : 'grab') : 'default' }}
              onMouseDown={e => sliderStart(e.clientX)}
              onMouseMove={e => { if (isDragging) sliderMove(e.clientX) }}
              onMouseUp={e => sliderEnd(e.clientX)}
              onMouseLeave={() => { if (isDragging) sliderEnd(sliderDragX.current ?? 0) }}
              onTouchStart={e => sliderStart(e.touches[0].clientX)}
              onTouchMove={e => { if (isDragging) sliderMove(e.touches[0].clientX) }}
              onTouchEnd={e => sliderEnd(e.changedTouches[0].clientX)}
            >
              {imgs.length > 0 ? (
                <>
                  <div
                    className={`cdm-slider-track${trackAnimate ? ' animate' : ''}`}
                    style={{ transform: `translateX(calc(-${activeImg * 100}% + ${sliderDelta}px))` }}
                  >
                    {imgs.map((src, i) => (
                      <div key={i} className="cdm-slider-slide">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img src={src} alt={car.title} draggable={false} />
                      </div>
                    ))}
                  </div>

                  {/* Prev/next arrows */}
                  {imgs.length > 1 && (
                    <>
                      <button className="cdm-arr cdm-arr-l" onClick={e => { e.stopPropagation(); goPrev() }}
                        disabled={activeImg === 0} aria-label="Vorheriges Bild">
                        <IconChevLeft />
                      </button>
                      <button className="cdm-arr cdm-arr-r" onClick={e => { e.stopPropagation(); goNext() }}
                        disabled={activeImg === imgs.length - 1} aria-label="Nächstes Bild">
                        <IconChevRight />
                      </button>
                    </>
                  )}

                  {/* Zoom button — prominent pill, bottom-center */}
                  <button className="cdm-zoom-btn" onClick={e => { e.stopPropagation(); openZoom() }} aria-label="Bild vergrößern">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                      <circle cx="11" cy="11" r="7"/><path d="M21 21l-4.35-4.35"/>
                      <line x1="11" y1="8" x2="11" y2="14"/><line x1="8" y1="11" x2="14" y2="11"/>
                    </svg>
                    <span>Zoomen</span>
                  </button>
                </>
              ) : (
                <div className="cdm-no-img">Kein Bild verfügbar</div>
              )}
            </div>

            {/* Gallery footer: thumbnails + counter + scrubber */}
            {imgs.length > 1 && (
              <div className="cdm-gallery-foot">
                <div className="cdm-thumbs-row">
                  <button className="cdm-thumb-nav" onClick={goPrev} disabled={activeImg === 0} aria-label="Zurück">
                    <IconChevLeft />
                  </button>
                  <div className="cdm-thumbs" ref={thumbsRef}>
                    {imgs.map((src, i) => (
                      <button
                        key={i}
                        className={`cdm-thumb${i === activeImg ? ' active' : ''}`}
                        onClick={() => goTo(i)}
                        aria-label={`Bild ${i + 1}`}
                      >
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img src={src} alt="" loading="lazy" />
                      </button>
                    ))}
                  </div>
                  <button className="cdm-thumb-nav" onClick={goNext} disabled={activeImg === imgs.length - 1} aria-label="Weiter">
                    <IconChevRight />
                  </button>
                </div>

                {/* Counter above scrubber */}
                <div className="cdm-img-counter-row">
                  <span className="cdm-img-count-text">{activeImg + 1} / {imgs.length}</span>
                </div>

                {/* Scrubber */}
                <div className="cdm-scrubber">
                  <input
                    type="range"
                    min={0}
                    max={imgs.length - 1}
                    value={activeImg}
                    onChange={e => goTo(Number(e.target.value))}
                    className="cdm-scrubber-input"
                    aria-label="Bild auswählen"
                  />
                </div>
              </div>
            )}
          </div>

          {/* ── Details ───────────────────────────── */}
          <div className="cdm-details">

            {/* Scrollable body — everything except the action buttons */}
            <div className="cdm-scroll-wrap">
            <div className="cdm-details-body" ref={scrollBodyRef} onScroll={handleBodyScroll}>

              <div>
                <div className="cdm-brand-row">
                  <BrandLogo brand={brand} className="brand-badge-mono" size="lg" mono />
                  {car.isOffer && <span className="cdm-offer-tag">Angebot</span>}
                </div>
                <h2 className="cdm-title">{car.title}</h2>
                <div className="cdm-title-actions">
                  <button className={`cdm-fav-btn${isFav ? ' on' : ''}`} onClick={onFav} title={isFav ? 'Aus Merkliste entfernen' : 'Zur Merkliste'}>
                    <svg width="13" height="13" viewBox="0 0 24 24" fill={isFav ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>
                    {isFav ? 'Gespeichert' : 'Merkliste'}
                  </button>
                  <button className="cdm-share-btn" onClick={handleShare} title="Fahrzeug teilen">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>
                    Teilen
                  </button>
                </div>
                <div className="cdm-price">
                  {car.price > 0
                    ? <>{car.price.toLocaleString('de-AT')} €<small> inkl. MwSt.</small></>
                    : car.priceText
                  }
                </div>
              </div>

              <div className="cdm-section">
                <h4 className="cdm-section-title">Fahrzeugdaten</h4>
                <div className="cdm-specs">
                  {car.year   != null && <SpecRow label="Baujahr"        value={String(car.year)}                                icon={<IcCalendar/>} />}
                  {car.km     != null && <SpecRow label="Kilometerstand" value={`${car.km.toLocaleString('de-AT')} km`}         icon={<IcGauge/>} />}
                  {car.fuel          && <SpecRow label="Kraftstoff"      value={car.fuel}                                       icon={<IcFuel/>} />}
                  {car.trans         && <SpecRow label="Getriebe"        value={car.trans}                                      icon={<IcGear/>} />}
                  {car.power  != null && <SpecRow label="Leistung"       value={`${car.power} PS`}                              icon={<IcZap/>} />}
                  {car.body          && <SpecRow label="Karosserie"      value={car.body}                                       icon={<IcCar/>} />}
                  {(detail?.seats  ?? car.seats)  != null && <SpecRow label="Sitze"       value={String(detail?.seats  ?? car.seats)}   icon={<IcSeat/>} />}
                  {(detail?.owners ?? car.owners) != null && <SpecRow label="Vorbesitzer" value={String(detail?.owners ?? car.owners)}  icon={<IcUser/>} />}
                  <SpecRow label="Zustand" value={(detail?.condition?.trim() || car.condition?.trim() || 'Gebraucht')} icon={<IcShield/>} />
                </div>
              </div>

              {equip.length > 0 && (
                <div className="cdm-section">
                  <h4 className="cdm-section-title">Ausstattung &amp; Extras</h4>
                  <div className="cdm-equip-grid">
                    {(showAllEquip ? equip : equip.slice(0, 8)).map((e, i) => (
                      <span key={i} className="equip-chip">{e}</span>
                    ))}
                  </div>
                  {equip.length > 8 && (
                    <button className="cdm-desc-toggle" onClick={() => setShowAllEquip(s => !s)}>
                      {showAllEquip
                        ? <><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M18 15l-6-6-6 6"/></svg> Weniger</>
                        : <><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M6 9l6 6 6-6"/></svg> {equip.length - 8} weitere Extras</>
                      }
                    </button>
                  )}
                </div>
              )}

              {desc && (
                <div className="cdm-section">
                  <h4 className="cdm-section-title">Beschreibung</h4>
                  <pre className={`cdm-desc${showFullDesc ? ' cdm-desc-open' : ''}`}>
                    {desc}
                  </pre>
                  {desc.length > 200 && (
                    <div className="cdm-desc-footer">
                      <button className="cdm-desc-toggle" onClick={() => setShowFullDesc(s => !s)}>
                        {showFullDesc
                          ? <><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M18 15l-6-6-6 6"/></svg> Weniger anzeigen</>
                          : <><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><path d="M6 9l6 6 6-6"/></svg> Mehr anzeigen</>
                        }
                      </button>
                    </div>
                  )}
                </div>
              )}

              {/* ── Finanzierungsrechner ─────────────────────── */}
              {car.price > 0 && (
                <div className="cdm-section">
                  <h4 className="cdm-section-title">Finanzierungsrechner</h4>
                  <div className="cdm-calc">
                    <div className="cdm-calc-row">
                      <label className="cdm-calc-label">Anzahlung</label>
                      <div className="cdm-calc-input-wrap">
                        <span className="cdm-calc-prefix">€</span>
                        <input type="number" className="cdm-calc-input" min={0} max={car.price}
                          value={calcAnzahlung}
                          onChange={e => setCalcAnzahlung(Math.min(car.price, Math.max(0, +e.target.value)))} />
                      </div>
                    </div>
                    <div className="cdm-calc-row">
                      <label className="cdm-calc-label">Laufzeit</label>
                      <select className="cdm-calc-select" value={calcLaufzeit} onChange={e => setCalcLaufzeit(+e.target.value)}>
                        {[12,24,36,48,60,72,84].map(m => <option key={m} value={m}>{m} Monate</option>)}
                      </select>
                    </div>
                    <div className="cdm-calc-row">
                      <label className="cdm-calc-label">Zinssatz</label>
                      <div className="cdm-calc-input-wrap">
                        <input type="number" className="cdm-calc-input" min={0.1} max={30} step={0.1}
                          value={calcZins}
                          onChange={e => setCalcZins(Math.max(0.1, +e.target.value))} />
                        <span className="cdm-calc-suffix">%</span>
                      </div>
                    </div>
                    <div className="cdm-calc-result">
                      <div className="cdm-calc-rate">
                        € {calcMonthly > 0 ? Math.ceil(calcMonthly).toLocaleString('de-AT') : '—'}
                        <span className="cdm-calc-rate-unit">/ Monat</span>
                      </div>
                      <div className="cdm-calc-breakdown">
                        Finanzierungssumme: € {(car.price - calcAnzahlung).toLocaleString('de-AT')} &nbsp;·&nbsp;
                        Gesamtkosten: € {calcMonthly > 0 ? Math.ceil(calcMonthly * calcLaufzeit + calcAnzahlung).toLocaleString('de-AT') : '—'}
                      </div>
                      <div className="cdm-calc-disclaimer">Unverbindliche Beispielrechnung. Kein Angebot zur Kreditvergabe.</div>
                    </div>
                  </div>
                </div>
              )}

              {/* ── Ähnliche Fahrzeuge ───────────────────────── */}
              {similarCars.length > 0 && (
                <div className="cdm-section">
                  <h4 className="cdm-section-title">Fahrzeuge in ähnlicher Preiskategorie</h4>
                  <div className="cdm-similar-row">
                    {similarCars.map(sc => (
                      <button key={sc.id} className="cdm-similar-card" onClick={() => onCarSelect?.(sc)}>
                        <div className="cdm-similar-img">
                          {sc.image
                            // eslint-disable-next-line @next/next/no-img-element
                            ? <img src={sc.image} alt={sc.title} />
                            : <div className="cdm-similar-placeholder" />}
                        </div>
                        <div className="cdm-similar-info">
                          <span className="cdm-similar-title">{sc.title}</span>
                          <span className="cdm-similar-price">
                            {sc.price > 0 ? `€ ${sc.price.toLocaleString('de-AT')}` : sc.priceText}
                          </span>
                          {sc.km != null && <span className="cdm-similar-km">{sc.km.toLocaleString('de-AT')} km</span>}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}


            </div>{/* end cdm-details-body */}

            {/* Scroll-down indicator — visibility toggled directly via ref */}
            <div ref={cdmIndicatorRef} className="cv2-scroll-indicator" style={{ display: 'none' }}>
              <div className="cv2-scroll-indicator-fade" />
              <div className="cv2-scroll-indicator-btn" onClick={() => scrollBodyRef.current?.scrollBy({ top: 220, behavior: 'smooth' })}>
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M5 9l7 7 7-7"/>
                </svg>
              </div>
            </div>
            {/* Custom red scrollbar */}
            <div className="cv2-custom-sb" aria-hidden="true">
              <div ref={cdmThumbRef} className="cv2-custom-sb-thumb" />
            </div>

            </div>{/* end cdm-scroll-wrap */}

            {/* Fixed footer — always visible, never scrolled away */}
            <div className="cdm-actions">
              <button className="cdm-book-btn" onClick={onBook}>
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>
                </svg>
                Probefahrt anfragen
              </button>
              <button className="cdm-ask-btn" onClick={handleAsk}>
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
                Frage stellen
              </button>
            </div>
            {shareToast && <div className="cdm-share-toast">Link kopiert!</div>}

          </div>
        </div>
      </div>

      {/* ── Kontakt Modal ────────────────────────────────────────── */}
      {showKontakt && (
        <CarKontaktModal
          carTitle={car.title}
          carPrice={car.price}
          carPriceText={car.priceText}
          onClose={() => setShowKontakt(false)}
        />
      )}

      {/* ── Zoom overlay — premium glass lightbox ─────────────── */}
      {zoomOpen && imgs.length > 0 && (
        <div className="cdm-zoom-backdrop" onClick={closeZoom}>

          {/* Top row: title + close — centered */}
          <div className="cdm-zoom-topbar" onClick={e => e.stopPropagation()}>
            <span className="cdm-zoom-title">{car.title}</span>
            <button className="cdm-zoom-close" onClick={e => { e.stopPropagation(); closeZoom() }} aria-label="Schliessen">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
                <path d="M18 6 6 18M6 6l12 12"/>
              </svg>
              <span className="cdm-zoom-close-label">Schliessen</span>
            </button>
          </div>

          {/* Horizontal zoom bar — below topbar */}
          <div className="cdm-zoom-zoombar" onClick={e => e.stopPropagation()}>
            <span className="cdm-zoom-zoombar-label">1x</span>
            <input
              type="range" min={100} max={500} step={5}
              value={Math.round(zoomScale * 100)}
              onChange={e => {
                const s = Number(e.target.value) / 100
                setZoomScale(s)
                if (s <= 1) { setPanX(0); setPanY(0) }
              }}
              className="cdm-zoom-zoombar-range"
              aria-label="Zoom-Stufe"
            />
            <span className="cdm-zoom-zoombar-label">5x</span>
            <span className="cdm-zoom-zoombar-pct">{Math.round(zoomScale * 100)}%</span>
            <span className="cdm-zoom-zoombar-sep" />
            <span className="cdm-zoom-zoombar-hint">Scrollen oder Klicken für 2,5x</span>
          </div>

          {/* Side navigation arrows */}
          {imgs.length > 1 && (
            <>
              <button className="cdm-zoom-nav cdm-zoom-prev"
                onClick={e => { e.stopPropagation(); goPrev(); setZoomScale(1); setPanX(0); setPanY(0) }}
                disabled={activeImg === 0} aria-label="Vorheriges Bild">
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M15 18l-6-6 6-6"/>
                </svg>
              </button>
              <button className="cdm-zoom-nav cdm-zoom-next"
                onClick={e => { e.stopPropagation(); goNext(); setZoomScale(1); setPanX(0); setPanY(0) }}
                disabled={activeImg === imgs.length - 1} aria-label="Nächstes Bild">
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M9 18l6-6-6-6"/>
                </svg>
              </button>
            </>
          )}

          {/* The image */}
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={imgs[activeImg]}
            alt={car.title}
            className="cdm-zoom-img"
            draggable={false}
            style={{
              transform: `translate(${panX}px, ${panY}px) scale(${zoomScale})`,
              cursor: zoomScale > 1 ? (isPanning ? 'grabbing' : 'grab') : 'zoom-in',
              transition: isPanning ? 'none' : 'transform .14s cubic-bezier(.4,0,.2,1)',
            }}
            onClick={onZoomClick}
            onWheel={e => setZoomScale(s => {
              const next = Math.min(5, Math.max(1, s * (1 - e.deltaY * 0.002)))
              if (next === 1) { setPanX(0); setPanY(0) }
              return next
            })}
            onMouseDown={e => { e.stopPropagation(); onZoomPanStart(e.clientX, e.clientY) }}
            onMouseMove={e => onZoomPanMove(e.clientX, e.clientY)}
            onMouseUp={() => onZoomPanEnd()}
            onMouseLeave={() => onZoomPanEnd()}
          />

          {/* (vertical slider removed — zoom bar is now at top) */}

          {/* Bottom bar: counter + image scrubber + hint */}
          <div className="cdm-zoom-bottombar" onClick={e => e.stopPropagation()}>
            {imgs.length > 1 && (
              <>
                <span className="cdm-zoom-imgcount">{activeImg + 1} / {imgs.length}</span>
                <div className="cdm-zoom-imgtrack">
                  <span className="cdm-zoom-imgtrack-label">1</span>
                  <input
                    type="range" min={0} max={imgs.length - 1}
                    value={activeImg}
                    onChange={e => { goTo(Number(e.target.value)); setZoomScale(1); setPanX(0); setPanY(0) }}
                    className="cdm-zoom-imgtrack-range"
                    aria-label="Bild auswaehlen"
                  />
                  <span className="cdm-zoom-imgtrack-label">{imgs.length}</span>
                </div>
              </>
            )}
            <span className="cdm-zoom-hint">
              Nutzen Sie den Schieberegler um die Anzahl der Bilder zu wechseln
            </span>
          </div>

        </div>
      )}
    </>
  )
}

export { BrandLogo, BRAND_STYLE, BRAND_ABBR }
